import string

def encode(message):
    vowels = string.ascii_lowercase[0:5]
    vowel_replacements = string.ascii_lowercase[2:7]
    encoded_message = []

    for char in message:
        if char.islower():
            if char in vowels:
                encoded_message.append(vowel_replacements[vowels.index(char)])
            else:
                encoded_message.append(char.upper())
        elif char.isupper():
            if char in vowels:
                encoded_message.append(vowel_replacements[vowels.index(char.lower())])
            else:
                encoded_message.append(char.lower())
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)
